begin;
select no_plan();
insert into auth.users(id,email) select ('d1300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'d-coord-tap-'||n||'@planets.invalid' from generate_series(1,7) n;
insert into public.profiles(id,display_name) select id,'Fictional coordination person' from auth.users where email like 'd-coord-tap-%';
insert into private.community_groups(id,name,description,group_kind,volunteering_focus,publication_state,original_actor_id)
select ('d1310000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Fictional coordination group '||n,'A synthetic group for coordination authorization.','informal',false,'published',('d1300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,5) n;
insert into private.community_group_managers(group_id,profile_id,appointed_by_actor_id) select id,original_actor_id,original_actor_id from private.community_groups where id::text like 'd131%';
insert into private.group_delegates(id,group_id,profile_id,initial_role,delegate_role,granted_by) values
('d1320000-0000-4000-8000-000000000001','d1310000-0000-4000-8000-000000000003','d1300000-0000-4000-8000-000000000006','co_organizer','co_organizer','d1300000-0000-4000-8000-000000000003'),
('d1320000-0000-4000-8000-000000000002','d1310000-0000-4000-8000-000000000004','d1300000-0000-4000-8000-000000000006','co_creator','co_creator','d1300000-0000-4000-8000-000000000004');
create temp table coord_result(kind text,value jsonb); grant all on coord_result to authenticated;
insert into private.group_memberships(group_id,profile_id,admitted_by) values
('d1310000-0000-4000-8000-000000000003','d1300000-0000-4000-8000-000000000006','d1300000-0000-4000-8000-000000000003'),
('d1310000-0000-4000-8000-000000000003','d1300000-0000-4000-8000-000000000007','d1300000-0000-4000-8000-000000000003');
create function pg_temp.person(n integer) returns uuid language sql as $$ select ('d1300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid $$;
create function pg_temp.grp(n integer) returns uuid language sql as $$ select ('d1310000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid $$;
create function pg_temp.result(kind text,key text) returns uuid language sql as $$ select (value->>key)::uuid from coord_result r where r.kind=$1 $$;
create function pg_temp.act(n integer) returns text language sql as $$ select set_config('request.jwt.claim.sub',pg_temp.person(n)::text,true) $$;
grant execute on function pg_temp.act(integer),pg_temp.person(integer),pg_temp.grp(integer),pg_temp.result(text,text) to authenticated;
set local role authenticated;
select pg_temp.act(1);
insert into coord_result values('request',public.submit_group_contact_request(pg_temp.person(1),gen_random_uuid(),pg_temp.grp(1),pg_temp.grp(2),'collaboration','Private original title','Private original note.'));
select pg_temp.act(2);
insert into coord_result values('source',public.accept_group_contact_request(pg_temp.person(2),gen_random_uuid(),pg_temp.result('request','request_id')));
select public.send_group_contact_message(pg_temp.person(2),gen_random_uuid(),pg_temp.result('source','chat_id'),'Secret original history must stay private.');
select pg_temp.act(1);
select throws_ok($$select public.submit_group_coordination_proposal(pg_temp.person(1),gen_random_uuid(),pg_temp.result('source','chat_id'),array[pg_temp.grp(1)],'Fresh purpose','Fresh invitation.')$$,'42501',null,'original group cannot supply its own independent consent');
insert into coord_result values('proposal',public.submit_group_coordination_proposal(pg_temp.person(1),'d1330000-0000-4000-8000-000000000001',pg_temp.result('source','chat_id'),array[pg_temp.grp(3),pg_temp.grp(4)],'Fresh coordination','Fresh invitation authored explicitly.'));
select is(public.submit_group_coordination_proposal(pg_temp.person(1),'d1330000-0000-4000-8000-000000000001',pg_temp.result('source','chat_id'),array[pg_temp.grp(3),pg_temp.grp(4)],'Fresh coordination','Fresh invitation authored explicitly.')->>'replayed','true','propose replay preserves exact original intent');
select throws_ok($$select public.submit_group_coordination_proposal(pg_temp.person(1),'d1330000-0000-4000-8000-000000000001',pg_temp.result('source','chat_id'),array[pg_temp.grp(3)],'Fresh coordination','Fresh invitation authored explicitly.')$$,'PT409',null,'same key cannot change proposed audience');
select pg_temp.act(7);
select throws_ok($$select public.get_own_group_coordination_proposal(pg_temp.person(7),pg_temp.result('proposal','coordination_id'))$$,'42501',null,'ordinary unrelated account cannot read staged invitation');
select throws_ok($$select * from private.group_coordination_seats$$,'42501',null,'authenticated direct table access denied');
select pg_temp.act(6);
insert into coord_result values('invite',public.get_own_group_coordination_proposal(pg_temp.person(6),pg_temp.result('proposal','coordination_id')));
select is((select value->>'source_chat_id' from coord_result where kind='invite'),null::text,'invite contains no original link/ID');
select is((select value->>'chat_id' from coord_result where kind='invite'),null::text,'staging creates no chat');
select is((select value->>'request_message' from coord_result where kind='invite'),'Fresh invitation authored explicitly.','only fresh note disclosed');
select is(jsonb_array_length((select value->'audience' from coord_result where kind='invite')),0,'original peer identity withheld until original explicit audience consent');
select is((public.get_own_message_unread_summary_v2(pg_temp.person(6))->>'groups')::integer,0,'invitation is not a human-message unread');
select is(jsonb_array_length(public.list_own_scoped_conversation_items_v6(pg_temp.person(6),'groups',10)),0,'no staged chat preview');
select is(jsonb_array_length(public.list_own_structured_request_message_items_v2(pg_temp.person(6),10)),0,'installed Requests v2 excludes new kind before limit');
select is(jsonb_array_length(public.list_own_structured_request_message_items_v3(pg_temp.person(6),10)),1,'Requests v3 exposes authorized proposal');
select public.claim_group_coordination_seat(pg_temp.person(6),gen_random_uuid(),pg_temp.result('proposal','coordination_id'),1,pg_temp.grp(3));
select throws_ok($$select public.claim_group_coordination_seat(pg_temp.person(6),gen_random_uuid(),pg_temp.result('proposal','coordination_id'),2,pg_temp.grp(4))$$,'42501',null,'one person representing several groups cannot supply two seats');
select throws_ok($$select public.confirm_group_coordination_audience(pg_temp.person(6),gen_random_uuid(),pg_temp.result('proposal','coordination_id'),2)$$,'PT409',null,'claim does not consent to incomplete audience');
select pg_temp.act(4);
select public.claim_group_coordination_seat(pg_temp.person(4),gen_random_uuid(),pg_temp.result('proposal','coordination_id'),2,pg_temp.grp(4));
select pg_temp.act(1);
select throws_ok($$select public.confirm_group_coordination_audience(pg_temp.person(1),gen_random_uuid(),pg_temp.result('proposal','coordination_id'),2)$$,'PT409',null,'stale version cannot cover changed human audience');
select public.confirm_group_coordination_audience(pg_temp.person(1),gen_random_uuid(),pg_temp.result('proposal','coordination_id'),3);
select pg_temp.act(6);
select is(public.get_own_group_coordination_proposal(pg_temp.person(6),pg_temp.result('proposal','coordination_id'))->>'audience_disclosed','false','one original consent does not expose the other human');
select pg_temp.act(2);
select public.confirm_group_coordination_audience(pg_temp.person(2),gen_random_uuid(),pg_temp.result('proposal','coordination_id'),3);
select pg_temp.act(6);
select is(jsonb_array_length(public.get_own_group_coordination_proposal(pg_temp.person(6),pg_temp.result('proposal','coordination_id'))->'audience'),4,'both originals authorize complete named audience');
select public.confirm_group_coordination_audience(pg_temp.person(6),gen_random_uuid(),pg_temp.result('proposal','coordination_id'),3);
select pg_temp.act(4);
insert into coord_result values('room',public.confirm_group_coordination_audience(pg_temp.person(4),'d1330000-0000-4000-8000-000000000002',pg_temp.result('proposal','coordination_id'),3));
select is((select value->>'outcome' from coord_result where kind='room'),'active','last consent atomically creates a fresh room');
select is(public.confirm_group_coordination_audience(pg_temp.person(4),'d1330000-0000-4000-8000-000000000002',pg_temp.result('proposal','coordination_id'),3)->>'chat_id',pg_temp.result('room','chat_id')::text,'lost final response recovers exactly one room');
select is(jsonb_array_length(public.get_own_group_contact_feed(pg_temp.person(4),pg_temp.result('room','chat_id'))->'items'),0,'fresh history excludes all original messages');
select throws_ok($$select public.get_own_group_contact_feed(pg_temp.person(4),pg_temp.result('source','chat_id'))$$,'42501',null,'fresh admission never grants original history');
select is(public.get_own_group_coordination_for_conversation(pg_temp.person(4),pg_temp.result('room','chat_id'))->>'source_chat_id',null::text,'fresh room context never exposes unauthorized source');
select pg_temp.act(3);
select is(public.get_own_group_coordination_proposal(pg_temp.person(3),pg_temp.result('proposal','coordination_id'))->>'title',null::text,'nonaccepting group Creator receives minimal resolved metadata');
select throws_ok($$select public.get_own_group_contact_conversation(pg_temp.person(3),pg_temp.result('room','chat_id'))$$,'42501',null,'manager does not inherit admitted delegate history');
reset role;
select is((select count(*) from private.group_contact_conversations where coordination_proposal_id=pg_temp.result('proposal','coordination_id')),1::bigint,'unique activation anchor');
select is((select count(*) from private.group_contact_admissions where conversation_id=pg_temp.result('room','chat_id')),4::bigint,'exact named human/group seats');
select is((select count(*) from private.group_memberships where group_id::text like 'd131%'),2::bigint,'coordination changes no pre-existing membership');
update private.group_delegates set revoked_at=clock_timestamp(),revoked_by=pg_temp.person(3) where id='d1320000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.act(6);
select throws_ok($$select public.get_own_group_contact_feed(pg_temp.person(6),pg_temp.result('room','chat_id'))$$,'42501',null,'revoked delegate loses new room immediately');
select is(public.get_own_group_coordination_proposal(pg_temp.person(6),pg_temp.result('proposal','coordination_id'))->>'request_message',null::text,'former actor receives own metadata only');
select lives_ok($$select public.submit_moderation_report(pg_temp.person(6),gen_random_uuid(),'other','A previously seen synthetic invitation is reported.','group_coordination_proposal',pg_temp.result('proposal','coordination_id'))$$,'known invitation reporting survives revocation');
select is(jsonb_array_length(to_jsonb(array(select r from public.list_own_moderation_reports_v2(pg_temp.person(6),10) r))),0,'old report parser excludes coordination');
select is(jsonb_array_length(to_jsonb(array(select r from public.list_own_moderation_reports_v3(pg_temp.person(6),10) r))),1,'versioned own report scope includes coordination');
select pg_temp.act(1);
select is(public.get_own_group_contact_conversation(pg_temp.person(1),pg_temp.result('room','chat_id'))->>'is_read_only','false','three remaining eligible participants can still coordinate');
insert into coord_result values('replacement',public.submit_group_coordination_proposal(pg_temp.person(1),gen_random_uuid(),pg_temp.result('source','chat_id'),array[pg_temp.grp(5)],'Fresh replacement','A fresh synthetic replacement round.'));
select pg_temp.act(5);
select public.claim_group_coordination_seat(pg_temp.person(5),gen_random_uuid(),pg_temp.result('replacement','coordination_id'),1,pg_temp.grp(5));
select pg_temp.act(1);
select public.confirm_group_coordination_audience(pg_temp.person(1),gen_random_uuid(),pg_temp.result('replacement','coordination_id'),2);
select is((public.replace_group_coordination_targets(pg_temp.person(1),gen_random_uuid(),pg_temp.result('replacement','coordination_id'),2,array[pg_temp.grp(5)])->>'version')::integer,3,'same-group replacement explicitly starts another selection round');
select is(public.get_own_group_coordination_proposal(pg_temp.person(1),pg_temp.result('replacement','coordination_id'))->>'own_confirmed','false','same-group replacement invalidates earlier original consent');
select is(public.get_own_group_coordination_proposal(pg_temp.person(1),pg_temp.result('replacement','coordination_id'))->>'all_seats_named','false','same-group replacement retires the previous extra human');
select public.leave_group_contact_conversation(pg_temp.person(1),gen_random_uuid(),pg_temp.result('source','chat_id'));
select lives_ok($$select public.get_own_group_contact_feed(pg_temp.person(1),pg_temp.result('room','chat_id'))$$,'leaving source does not revoke separate fresh admission');
select is(public.get_own_group_coordination_for_conversation(pg_temp.person(1),pg_temp.result('room','chat_id'))->>'request_message','Fresh invitation authored explicitly.','fresh room context independent of later source exit');
reset role;
select * from finish();
rollback;
